try{(function(){"use strict";if(!window.MC||!MC.reg||MC.tests.audit)return;var a=[["Nahi","No"],["Haan","Yes"]],e="#16a34a",b="#65a30d",x="#d97706",j="#ea580c",h="#dc2626",g=["Ye hamari apni checklist hai, validated test nahi. Iska koi official cut-off nahi, ye sirf batati hai ki kitni baatein aap par lagu hui.","This is our own checklist, not a validated test. It has no official cut-off; it only shows how many points apply to you."],T=function(Z,$,z){return z?[Z,$,z]:[Z,$]},o=function(Z,$,z){var B=0,D;for(D=$;D<=z;D++)B+=Z[D]||0;return B},t=["Madad ke liye: Tele-MANAS 14416 (24x7), Nasha-mukti helpline 14446.","For help: Tele-MANAS 14416 (24x7), national drug de-addiction helpline 14446."],C=[["Kabhi nahi","Never"],["Mahine me 1 baar ya kam","Monthly or less"],["Mahine me 2 se 4 baar","2 to 4 times a month"],["Hafte me 2 se 3 baar","2 to 3 times a week"],["Hafte me 4 ya zyada baar","4 or more times a week"]],s=[["Kabhi nahi","Never"],["Mahine se kam","Less than monthly"],["Har mahine","Monthly"],["Har hafte","Weekly"],["Roz ya lagbhag roz","Daily or almost daily"]],p=[["1 ya 2","1 or 2"],["3 ya 4","3 or 4"],["5 ya 6","5 or 6"],["7 se 9","7 to 9"],["10 ya zyada","10 or more"]],r=[["Nahi, kabhi nahi","No, never"],["Haan, par pichhle 1 saal me nahi","Yes, but not in the past year"],["Haan, pichhle 1 saal me","Yes, during the past year"]],u=[["Nahi","No"],["Haan","Yes"]];MC.reg({id:"audit",name:["Alcohol use","Alcohol use"],sub:["Sharab ke istemal ka check, 10 sawal","Alcohol use check, 10 questions"],max:40,opts:C,intro:["Pichhle 1 saal ke baare me jawab dein. 1 drink = lagbhag 10 gram sharab: ek chhota peg (30 ml whisky/rum), 330 ml beer ya 120 ml wine. Agar aap sharab nahi peete to har sawal me pehla option chunein.","Answer about the past year. One drink is about 10 g alcohol: a small 30 ml peg of spirits, 330 ml beer or 120 ml wine. If you do not drink, choose the first option on every question."],items:[T("Aap kitni baar sharab peete hain?","How often do you have a drink containing alcohol?",C),T("Jis din aap peete hain, us din aam taur par kitne drink lete hain?","On a typical drinking day, how many drinks do you have?",p),T("Ek hi mauke par 6 ya zyada drink kitni baar lete hain?","How often do you have 6 or more drinks on one occasion?",s),T("Pichhle 1 saal me kitni baar aisa hua ki ek baar peena shuru karne ke baad aap ruk nahi paaye?","In the past year, how often could you not stop drinking once you had started?",s),T("Pichhle 1 saal me kitni baar sharab ki wajah se aap wo kaam nahi kar paaye jo aapse umeed thi?","In the past year, how often did drinking make you fail to do what was expected of you?",s),T("Pichhle 1 saal me kitni baar subah-subah pehle drink ki zaroorat padi, taaki raat ke baad theek mehsoos karein?","In the past year, how often did you need a drink first thing in the morning to get going?",s),T("Pichhle 1 saal me kitni baar peene ke baad aapko guilt ya pachtawa hua?","In the past year, how often did you feel guilt or regret after drinking?",s),T("Pichhle 1 saal me kitni baar peene ke baad aapko pichhli raat ki baatein yaad nahi aayin?","In the past year, how often could you not remember the night before because of drinking?",s),T("Kya aapki sharab ki wajah se aapko ya kisi aur ko chot lagi hai?","Have you or someone else been injured because of your drinking?",r),T("Kya kisi rishtedar, dost ya doctor ne aapke peene par chinta jatayi ya use kam karne ko kaha?","Has a relative, friend or doctor been worried about your drinking or suggested you cut down?",r)],calc:function(Z){var $=o(Z,0,7)+2*(Z[8]||0)+2*(Z[9]||0),z=$<=7?[0,40,"Low risk",e,0]:$<=15?[0,40,"Hazardous use",x,1]:$<=19?[0,40,"Harmful use",j,2]:[0,40,"Possible dependence",h,3],B=$<=7?["Aapka sharab ka istemal kam risk wala hai. Sharab na peena sabse safe hai; pregnancy, dawai ya jigar/dil ki bimari me bilkul na peeyein.","Your alcohol use is low risk. Not drinking is safest; avoid alcohol completely in pregnancy, with some medicines, or with liver or heart disease."]:$<=15?["Aapka peena risk wale daayre me hai. Ek hafte ka hisaab rakhein, ek baar me bahut zyada peene se bachein aur hafte me kuch din bilkul na peeyein. Jitna kam, utna behtar. Chahein to doctor se baat karein.","Your drinking is in a risky range. Keep a weekly count, avoid heavy drinking in one sitting and keep some days alcohol-free. The less the better. Talk to a doctor if you like."]:$<=19?["Peena nuksan pahuncha raha lagta hai. Doctor ya counsellor se milkar kam karne ki yojana banayein aur 1 se 2 mahine baad ye check dobara karein.","Your drinking seems to be causing harm. See a doctor or counsellor to plan cutting down, and repeat this check in 1 to 2 months."]:["Ye score sharab par nirbharta ki sambhavna dikhata hai. Psychiatrist ya de-addiction doctor se jald milein. Agar aap roz peete hain to achanak band na karein: withdrawal me kampkampi, daure (seizure) ya bhram ho sakte hain. Doctor ki dekh-rekh me hi kam karein. "+t[0],"This score suggests possible alcohol dependence. Please see a psychiatrist or de-addiction doctor soon. If you drink daily, do not stop suddenly: withdrawal can cause shaking, seizures or confusion. Cut down only under a doctor's care. "+t[1]];return{s:$,b:z,lines:[["Cut-off (0 se 40): 8 se risk wala, 16 se nuksan wala, 20 se nirbharta ki sambhavna. Ye diagnosis nahi hai.","Cut-offs (0 to 40): 8 or more hazardous, 16 or more harmful, 20 or more possible dependence. This is not a diagnosis."]],adv:B}}}),MC.reg({id:"taps",name:["Substance use (quick screen)","Substance use (quick screen)"],sub:["Tobacco, sharab, nasha aur dawai ka chhota screen, 4 sawal","Quick screen for tobacco, alcohol, drugs and medicines, 4 questions"],max:16,opts:s,intro:["Pichhle 1 saal ke baare me jawab dein. Ye sirf shuruaati screen hai: kisi bhi jawab me 'Kabhi nahi' se upar ho to us cheez ka poora check bhi kar lein.","Answer about the past year. This is a first-step screen: if any answer is above Never, take the full check for that substance too."],items:[T("Pichhle 1 saal me kitni baar aapne tobacco ya nicotine (cigarette, bidi, gutka, khaini, vape) liya?","In the past year, how often did you use tobacco or nicotine (cigarettes, bidi, gutka, khaini, vape)?"),T("Pichhle 1 saal me kitni baar ek hi din me 5 ya zyada drink (mahilaon ke liye 4 ya zyada) liye?","In the past year, how often did you have 5 or more drinks in a day (4 or more for women)?"),T("Pichhle 1 saal me kitni baar aapne nasha liya, jaise bhang, ganja, charas, afeem, heroin, cocaine, stimulants ya inhalants?","In the past year, how often did you use drugs such as cannabis, opium, heroin, cocaine, stimulants or inhalants?"),T("Pichhle 1 saal me kitni baar aapne doctor ke bina likhi ya zyada matra me dawai (dard, neend ya anxiety ki goliyan, cough syrup) sirf nasha ya 'feeling' ke liye li?","In the past year, how often did you use prescription medicines (pain, sleep or anxiety pills, cough syrup) only for the feeling, in larger amounts than prescribed, or without a prescription?")],calc:function(Z){var $=o(Z,0,3),z=[["tobacco","tobacco"],["sharab","alcohol"],["nasha","drugs"],["dawai ka galat istemal","medicine misuse"]],B=[],D=[],N=0,G;for(G=0;G<4;G++)(Z[G]||0)>=1&&(B.push(z[G][0]),D.push(z[G][1]),Z[G]>=3&&(N=1));var E=B.length?N?[0,16,"Frequent use reported",j,2]:[0,16,"Some use reported",x,1]:[0,16,"No use reported",e,0],l=["Aage ke check: tobacco ke liye nicotine nirbharta check, sharab ke liye alcohol check, nasha aur dawai ke liye drug use ya cannabis ya substance involvement check.","Next checks: nicotine dependence for tobacco, the alcohol check for drinking, and the drug use, cannabis or substance involvement checks for drugs and medicines."];return{s:$,b:E,lines:[[B.length?"Upar ye cheezein dikhi: "+B.join(", ")+". "+l[0]:"Kisi me bhi use nahi dikha.",D.length?"These came up: "+D.join(", ")+". "+l[1]:"No use was reported."],["Ye routing screen hai, score se diagnosis nahi hota.","This is a routing screen; the score does not diagnose."]],adv:B.length?["Kuch istemal dikha hai. Isse zaroori nahi ki dikkat ho, par us cheez ka poora check lena achha rahega. Agar roz ya lagbhag roz use hai to doctor se baat karein. "+t[0],"Some use was reported. That does not mean there is a problem, but the full check for that substance is a good idea. If use is daily or almost daily, talk to a doctor. "+t[1]]:["Koi use nahi dikha. Shukriya.","No use reported. Thank you."]}}}),MC.reg({id:"dast",name:["Drug use","Drug use"],sub:["Nasha (sharab chhodkar) ka check, 10 sawal","Drug use check (not alcohol), 10 questions"],max:10,opts:a,intro:["Pichhle 12 mahine ke baare me jawab dein. 'Nasha' ka matlab sharab aur tobacco ko chhodkar: bhang, ganja, charas, afeem, heroin, cocaine, stimulants, inhalants, ya doctor ki salah ke bina li gayi dard/neend/anxiety ki goliyan.","Answer about the past 12 months. 'Drugs' means anything except alcohol and tobacco: cannabis, opium, heroin, cocaine, stimulants, inhalants, or pills for pain, sleep or anxiety taken without a prescription or in larger amounts."],items:[T("Kya aapne dawai ke maqsad ke bina nasha kiya hai?","Have you used drugs other than for medical reasons?"),T("Kya aap ek se zyada nashe ek saath lete hain?","Do you use more than one drug at a time?"),T("Kya aap jab chahein nasha chhod sakte hain?","Are you always able to stop using drugs when you want to?"),T("Kya nashe ke baad aapko blackout (yaad ka gap) ya flashback jaise anubhav hue hain?","Have you had blackouts or flashbacks as a result of drug use?"),T("Kya aap nashe ke baare me bura ya doshi mehsoos karte hain?","Do you ever feel bad or guilty about your drug use?"),T("Kya aapke ghar waale ya saathi aapke nashe ki shikayat karte hain?","Does your partner or a family member complain about your involvement with drugs?"),T("Kya nashe ki wajah se aapne parivaar ya zimmedariyon ko andekha kiya hai?","Have you neglected your family or responsibilities because of drug use?"),T("Kya nasha paane ke liye aapne galat ya gair-kanooni kaam kiye hain?","Have you done illegal activities in order to get drugs?"),T("Kya nasha band karne par aapko withdrawal (kampkampi, bechaini, dard) hua hai?","Have you had withdrawal symptoms when you stopped taking drugs?"),T("Kya nashe ki wajah se sehat ki dikkat hui hai, jaise yaaddasht kamzor hona, hepatitis, daure ya khoon beh jana?","Have you had medical problems because of drugs, such as memory loss, hepatitis, seizures or bleeding?")],calc:function(Z){var $=0,z;for(z=0;z<10;z++)Z[z]!==void 0&&($+=z==2?Z[z]==0?1:0:Z[z]);var B=$==0?[0,10,"No problems reported",e,0]:$<=2?[0,10,"Low level",b,1]:$<=5?[0,10,"Moderate level",x,2]:$<=8?[0,10,"Substantial level",j,3]:[0,10,"Severe level",h,3];return{s:$,b:B,lines:[["Cut-off (0 se 10): 1-2 kam, 3-5 madhyam, 6-8 kaafi, 9-10 gambhir. Sawal 3 ulta ginta hai. Ye diagnosis nahi hai.","Cut-offs (0 to 10): 1 to 2 low, 3 to 5 moderate, 6 to 8 substantial, 9 to 10 severe. Item 3 is reverse-scored. This is not a diagnosis."]],adv:$==0?["Koi dikkat nahi dikhi.","No problems were reported."]:$<=2?["Halka istemal ya dikkat dikhi. Apne use par nazar rakhein aur kam ya band karne ka soch sakte hain. Zaroorat ho to doctor se poochhein.","Some low-level use or problems show. Keep an eye on your use and consider cutting down or stopping. Ask a doctor if needed."]:$<=5?["Madhyam level ki dikkat dikhi. Doctor, psychiatrist ya counsellor se baat karein; shuru me madad lena sabse behtar rehta hai. "+t[0],"A moderate level of problems shows. Talk to a doctor, psychiatrist or counsellor; early help works best. "+t[1]]:["Nasha kaafi dikkat de raha lagta hai. Jald psychiatrist ya de-addiction kendra se milein. Agar aap roz leti/lete hain to achanak band na karein, kuch nashe (jaise sharab, neend ki goliyan) band karna khatarnak ho sakta hai; doctor ki dekh-rekh me karein. "+t[0],"Drug use seems to be causing major problems. Please see a psychiatrist or de-addiction centre soon. If you use daily, do not stop suddenly; stopping some drugs (such as alcohol or sleeping pills) can be dangerous, so do it under a doctor's care. "+t[1]]}}}),MC.reg({id:"cudit",name:["Cannabis use","Cannabis use"],sub:["Cannabis (bhang, ganja, charas) ka check, 8 sawal","Cannabis (bhang, ganja, charas) check, 8 questions"],max:32,opts:C,intro:["Pichhle 6 mahine ke baare me jawab dein. Cannabis me bhang, ganja, charas, weed shamil hain. Agar pichhle 6 mahine me nahi li, to pehle sawal me 'Kabhi nahi' chunein.","Answer about the past 6 months. Cannabis includes bhang, ganja, charas and weed. If you have not used it in the past 6 months, choose Never on the first question."],items:[T("Aap kitni baar cannabis lete hain?","How often do you use cannabis?",C),T("Jis din aap lete hain, us din aam taur par kitne ghante 'high' rehte hain?","On a typical day you use, how many hours are you high?",[["1 ghante se kam","Less than 1 hour"],["1 se 2 ghante","1 to 2 hours"],["3 se 4 ghante","3 to 4 hours"],["5 se 6 ghante","5 to 6 hours"],["7 ghante ya zyada","7 hours or more"]]),T("Kitni baar aisa hua ki ek baar shuru karne ke baad aap ruk nahi paaye?","How often could you not stop once you had started?",s),T("Kitni baar cannabis ki wajah se aap wo kaam nahi kar paaye jo aapse umeed thi?","How often did cannabis stop you from doing what was expected of you?",s),T("Kitni baar cannabis lene, ya uske baad theek hone me aapka bahut samay gaya?","How often did you spend a lot of time getting, using or recovering from cannabis?",s),T("Kitni baar cannabis ke baad aapko yaaddasht ya dhyan me dikkat hui?","How often did you have memory or concentration problems after using cannabis?",s),T("Kitni baar aapne aise mauke par li jahan khatra ho sakta tha, jaise gaadi chalana ya machine?","How often did you use it in a situation that could be physically dangerous, such as driving or using machinery?",s),T("Kya aapne kabhi cannabis kam ya band karne ke baare me socha hai?","Have you ever thought about cutting down or stopping cannabis?",[["Nahi, kabhi nahi","No, never"],["Haan, par pichhle 6 mahine me nahi","Yes, but not in the past 6 months"],["Haan, pichhle 6 mahine me","Yes, in the past 6 months"]])],calc:function(Z){if(Z[0]===0)return{s:0,b:[0,32,"No use",e,0],lines:[["Pichhle 6 mahine me use nahi, isliye score 0.","No use in the past 6 months, so the score is 0."]],adv:["Cannabis ka use nahi dikha. Shukriya.","No cannabis use reported. Thank you."]};var $=o(Z,0,6)+2*(Z[7]||0),z=$<=7?[0,32,"Low risk",e,0]:$<=11?[0,32,"Hazardous use",x,1]:[0,32,"Possible cannabis use disorder",j,2];return{s:$,b:z,lines:[["Cut-off (0 se 32): 8 se risk wala, 12 se cannabis use disorder ki sambhavna. Ye diagnosis nahi hai.","Cut-offs (0 to 32): 8 or more hazardous, 12 or more possible cannabis use disorder. This is not a diagnosis."]],adv:$<=7?["Kam risk. Use rakhein to kam rakhein, gaadi chalane se pehle bilkul na lein.","Low risk. If you use, keep it low and never before driving."]:$<=11?["Risk wala use dikh raha hai. Use kam karne ki koshish karein, hisaab rakhein aur doctor ya counsellor se baat karein. Cannabis yaaddasht, padhai aur mood par asar daal sakta hai.","A hazardous pattern shows. Try to cut down, keep count, and talk to a doctor or counsellor. Cannabis can affect memory, study and mood."]:["Cannabis use disorder ki sambhavna hai. Psychiatrist ya counsellor se poori jaanch karayein; therapy kaafi madad karti hai. "+t[0],"Cannabis use disorder is possible. Get a full assessment from a psychiatrist or counsellor; therapy helps a lot. "+t[1]]}}});var i=[["Sharab","Alcohol"],["Cannabis (bhang, ganja, charas)","Cannabis (bhang, ganja, charas)"],["Cocaine","Cocaine"],["Stimulants (meth, MDMA, speed)","Amphetamine-type stimulants (meth, MDMA, speed)"],["Inhalants (whitener, glue, petrol)","Inhalants (whitener, glue, petrol)"],["Neend ya anxiety ki goliyan (bina doctor ki salah)","Sedatives or sleeping pills (not prescribed)"],["Hallucinogens (LSD, mushroom, ketamine)","Hallucinogens (LSD, mushrooms, ketamine)"],["Opioids (heroin/smack, afeem, doda post, tramadol, codeine syrup)","Opioids (heroin, opium, poppy husk, tramadol, codeine syrup)"],["Koi aur nasha","Another drug"]],k=function(Z){return[["Kabhi nahi","Never"],["Ek ya do baar","Once or twice"],["Har mahine","Monthly"],["Har hafte","Weekly"],["Roz ya lagbhag roz","Daily or almost daily"]].slice(0,Z)},c=[0,2,3,4,6],n=[0,3,4,5,6],y=[0,4,5,6,7],m=[0,5,6,7,8],M=[0,3,6],f=[["Nahi, kabhi nahi","No, never"],["Haan, par pichhle 3 mahine me nahi","Yes, but not in the past 3 months"],["Haan, pichhle 3 mahine me","Yes, in the past 3 months"]];MC.reg({id:"assist",name:["Substance involvement (one substance)","Substance involvement (one substance)"],sub:["Ek nashe ka detail check, 8 sawal","Detailed check for one substance, 8 questions"],max:39,opts:a,intro:["Pehle ek cheez chunein jiske baare me jawab dena hai (tobacco ke liye alag nicotine check hai). Agar kai cheezein leti/lete hain to ye test har cheez ke liye dobara le sakte hain.","First pick one substance to answer about (tobacco has its own nicotine check). If you use several, repeat this check for each one."],items:[T("Aap kis cheez ke baare me jawab dena chahte hain?","Which substance do you want to answer about?",i),T("Pichhle 3 mahine me aapne use kitni baar li?","In the past 3 months, how often did you use it?",k(5)),T("Pichhle 3 mahine me kitni baar use lene ki tez ichha ya craving hui?","In the past 3 months, how often did you have a strong desire or urge to use it?",k(5)),T("Pichhle 3 mahine me kitni baar uski wajah se sehat, rishton, kanoon ya paison ki dikkat hui?","In the past 3 months, how often did using it cause health, social, legal or money problems?",k(5)),T("Pichhle 3 mahine me kitni baar uski wajah se aap wo kaam nahi kar paaye jo aapse umeed thi?","In the past 3 months, how often did using it stop you doing what was expected of you?",k(5)),T("Kya kisi dost, rishtedar ya kisi aur ne aapke use par chinta jatayi?","Has a friend, relative or anyone else expressed concern about your use?",f),T("Kya aapne use kam ya band karne ki koshish ki aur kar nahi paaye?","Have you tried to cut down or stop and failed?",f),T("Kya aapne kabhi doctor ki salah ke bina injection se nasha liya hai?","Have you ever injected a drug for a non-medical reason?",f)],calc:function(Z){var $=Z[0]||0,z=(c[Z[1]]||0)+(n[Z[2]]||0)+(y[Z[3]]||0)+(m[Z[4]]||0)+(M[Z[5]]||0)+(M[Z[6]]||0),B=$==0,D=B?10:3,N=26,G=z<=D?[0,39,"Lower risk",e,0]:z<=N?[0,39,"Moderate risk",x,2]:[0,39,"High risk",h,3],E=(Z[7]||0)>=1,l=i[$],A=z<=D?["Is cheez ke liye risk kam hai. Use rakhein to kam rakhein.","Risk for this substance is lower. If you use it, keep it low."]:z<=N?["Moderate risk hai: use se sehat ya zindagi par asar padne ka khatra hai. Kam karne ki salah ke liye doctor ya counsellor se baat karein. "+t[0],"Moderate risk: use may harm your health or life. Talk to a doctor or counsellor about cutting down. "+t[1]]:["High risk hai: nirbharta ya gambhir nuksan ki sambhavna hai. Jald psychiatrist ya de-addiction kendra se milein. "+t[0],"High risk: dependence or serious harm is possible. See a psychiatrist or de-addiction centre soon. "+t[1]];return z>D&&($==0||$==5||$==7)&&(A=[A[0]+" Dhyan rahe: "+($==7?"opioids me overdose ka khatra hota hai; doctor se overdose se bachav ke baare me poochhein.":"roz lene par achanak band karna khatarnak ho sakta hai (daure, bhram). Doctor ki dekh-rekh me kam karein."),A[1]+" Note: "+($==7?"opioids carry an overdose risk; ask a doctor about overdose prevention.":"stopping suddenly after daily use can be dangerous (seizures, confusion). Cut down under a doctor's care.")]),E&&(A=[A[0]+" Injection se nasha liya hai to needle kabhi share na karein aur HIV, hepatitis ki jaanch karayein.",A[1]+" Because you have injected, never share needles and get tested for HIV and hepatitis."]),{s:z,b:G,lines:[["Aapne chuna: "+l[0]+". Cut-off: "+(B?"sharab ke liye 0-10 kam, 11-26 madhyam, 27+ zyada":"0-3 kam, 4-26 madhyam, 27+ zyada")+" (0 se 39).","You chose: "+l[1]+". Cut-offs: "+(B?"for alcohol 0-10 lower, 11-26 moderate, 27+ high":"0-3 lower, 4-26 moderate, 27+ high")+" (0 to 39)."]],adv:A}}}),MC.reg({id:"ftnd",name:["Nicotine dependence","Nicotine dependence"],sub:["Cigarette/bidi ki nirbharta ka check, 6 sawal","Cigarette/bidi dependence check, 6 questions"],max:10,opts:a,intro:["Ye cigarette ya bidi peene walon ke liye hai. Bidi ko bhi cigarette ginein. Gutka ya khaini ke liye ye score sahi nahi hota, par quitline madad karti hai.","This is for people who smoke cigarettes or bidis; count a bidi as a cigarette. The score does not fit gutka or khaini, but the quitline can still help."],items:[T("Subah uthne ke kitni der baad aap pehli cigarette ya bidi peete hain?","How soon after waking do you smoke your first cigarette or bidi?",[["60 minute ke baad","After 60 minutes"],["31 se 60 minute me","31 to 60 minutes"],["6 se 30 minute me","6 to 30 minutes"],["5 minute ke andar","Within 5 minutes"]]),T("Jahan peena mana hai (mandir, aspatal, library) wahan na peena aapko mushkil lagta hai?","Do you find it hard not to smoke where it is not allowed (temples, hospitals, libraries)?",a),T("Din ki kaunsi cigarette chhodna sabse mushkil hoga?","Which cigarette would be hardest to give up?",[["Koi aur","Any other"],["Subah ki pehli","The first one in the morning"]]),T("Aap din me kitni cigarette ya bidi peete hain?","How many cigarettes or bidis do you smoke a day?",[["10 ya kam","10 or fewer"],["11 se 20","11 to 20"],["21 se 30","21 to 30"],["31 ya zyada","31 or more"]]),T("Kya aap subah ke pehle ghanton me baaki din se zyada peete hain?","Do you smoke more in the first hours after waking than during the rest of the day?",a),T("Kya aap din bhar bimar hokar bistar par ho tab bhi peete hain?","Do you smoke even when you are so ill that you are in bed most of the day?",a)],calc:function(Z){var $=o(Z,0,5),z=$<=2?[0,10,"Very low",e,0]:$<=4?[0,10,"Low",b,1]:$==5?[0,10,"Moderate",x,2]:$<=7?[0,10,"High",j,2]:[0,10,"Very high",h,3];return{s:$,b:z,lines:[["Cut-off (0 se 10): 0-2 bahut kam, 3-4 kam, 5 madhyam, 6-7 zyada, 8-10 bahut zyada nirbharta.","Cut-offs (0 to 10): 0-2 very low, 3-4 low, 5 moderate, 6-7 high, 8-10 very high dependence."]],adv:$<=4?["Nicotine par nirbharta kam hai, isliye chhodna aasaan rahega. Abhi chhod dein; Quitline 1800-11-2356 (free) madad karti hai.","Nicotine dependence is low, so quitting is easier. Quit now; the free National Tobacco Quitline 1800-11-2356 can help."]:["Nicotine par nirbharta madhyam se zyada hai. Chhodne me counselling aur doctor ki salah se nicotine replacement ya dawai kaafi madad karte hain. Quitline 1800-11-2356 (free) ya Tele-MANAS 14416 par baat karein. Bar-bar koshish karna normal hai.","Nicotine dependence is moderate to high. Counselling plus nicotine replacement or medicine, with a doctor's advice, helps a lot in quitting. Call the free Quitline 1800-11-2356 or Tele-MANAS 14416. Trying more than once is normal."]}}});var K=[["Kabhi nahi","Never"],["Kabhi-kabhi","Sometimes"],["Zyadatar","Most of the time"],["Lagbhag hamesha","Almost always"]];MC.reg({id:"pgsi",name:["Gambling","Gambling"],sub:["Jua / betting ka check, 9 sawal","Gambling and betting check, 9 questions"],max:27,opts:K,intro:["Pichhle 12 mahine ke baare me jawab dein. Jua me satta, lottery, cards, rummy ya betting apps, fantasy cricket, casino, online betting sab shamil hain. Agar nahi khela to 'Kabhi nahi' chunein.","Answer about the past 12 months. Gambling includes satta, lottery, cards, rummy or betting apps, fantasy cricket, casinos and online betting. If you did not gamble, choose Never."],items:[T("Kya aapne itna daav lagaya jitna haarne ki aap me kshamata nahi thi?","Have you bet more than you could really afford to lose?"),T("Kya wahi utejna paane ke liye aapko zyada paise lagane pade?","Have you needed to gamble with larger amounts to get the same excitement?"),T("Kya haare hue paise wapas jeetne ke liye aap agle din phir khelne gaye?","Have you gone back another day to try to win back money you lost?"),T("Kya jua khelne ke liye aapne paise udhaar liye ya kuch becha?","Have you borrowed money or sold something to get money to gamble?"),T("Kya aapko laga ki jue ki aapko dikkat ho sakti hai?","Have you felt you might have a problem with gambling?"),T("Kya jue ne aapki sehat ko nuksan pahunchaya, jaise tanav ya ghabrahat?","Has gambling caused you health problems, including stress or anxiety?"),T("Kya logon ne aapke jue ki aalochna ki ya kaha ki aapko jue ki dikkat hai?","Have people criticised your betting or told you that you have a gambling problem?"),T("Kya jue ne aapko ya ghar ko paison ki dikkat di?","Has gambling caused financial problems for you or your household?"),T("Kya aap apne jue ya uske nateejon par guilt mehsoos karte hain?","Have you felt guilty about the way you gamble or what happens when you gamble?")],calc:function(Z){var $=o(Z,0,8),z=$==0?[0,27,"Non-problem",e,0]:$<=2?[0,27,"Low risk",b,1]:$<=7?[0,27,"Moderate risk",x,2]:[0,27,"Problem gambling",h,3];return{s:$,b:z,lines:[["Cut-off (0 se 27): 0 koi dikkat nahi, 1-2 kam risk, 3-7 madhyam risk, 8+ jue ki dikkat.","Cut-offs (0 to 27): 0 non-problem, 1-2 low risk, 3-7 moderate risk, 8 or more problem gambling."]],adv:$==0?["Jue ki koi dikkat nahi dikhi.","No gambling problem was reported."]:$<=2?["Kam risk. Ek limit tay rakhein aur haare hue paise wapas jeetne ki koshish na karein.","Low risk. Set a limit and do not chase losses."]:$<=7?["Madhyam risk hai. Apni limit likh lein, betting apps ko block ya self-exclude karein, aur kisi bharose ke insaan ko batayein. Counsellor ya Tele-MANAS 14416 se baat kar sakte hain.","Moderate risk. Write down a limit, block or self-exclude from betting apps, and tell someone you trust. You can also talk to a counsellor or Tele-MANAS 14416."]:["Ye jue ki dikkat ke daayre me hai. Psychiatrist ya counsellor se milein; CBT kaafi madad karti hai. Kharch ke liye kisi apne ko cards, UPI aur bank access sambhalne dein. Agar karz ke dabav me khud ko nuksan ke vichaar aaye to abhi Tele-MANAS 14416 ya 112 par baat karein.","This is in the problem-gambling range. See a psychiatrist or counsellor; CBT helps a lot. Let someone you trust hold your cards, UPI and bank access. If debt pressure brings thoughts of harming yourself, call Tele-MANAS 14416 or 112 right now."]}}});var J=[["Kabhi nahi","Never"],["Kam hi","Rarely"],["Kabhi-kabhi","Sometimes"],["Aksar","Often"],["Bahut aksar","Very often"]];MC.reg({id:"igds",name:["Gaming","Gaming"],sub:["Gaming ki lat ka check, 9 sawal","Gaming habit check, 9 questions"],max:45,opts:J,intro:["Pichhle 12 mahine ke baare me jawab dein. Gaming me mobile, PC aur console ke online ya offline game (jaise BGMI, Free Fire, Minecraft) sab shamil hain. Sirf paise ya kaam ke liye khelna ginti me nahi.","Answer about the past 12 months. Gaming includes online or offline games on mobile, PC or console (such as BGMI, Free Fire, Minecraft). Playing only for work or pay does not count."],items:[T("Kya aap din bhar gaming ke baare me sochte rehte hain, pichhle game ya agle game ke baare me?","Do you spend a lot of time thinking about games, past sessions or the next one?"),T("Kya gaming kam karne ya rokne par aap bechain, chidchide ya udaas ho jaate hain?","Do you feel restless, irritable, anxious or sad when you try to cut down or stop gaming?"),T("Kya ab aapko pehle jitna maza paane ke liye zyada der khelna padta hai?","Do you need to play for longer to feel satisfied?"),T("Kya aap gaming kam karne ya rokne ki koshish me nakam hote hain?","Do you fail when you try to control or stop gaming?"),T("Kya gaming ki wajah se aap pehle ke shauk ya doosre maze ki cheezein chhod chuke hain?","Have you lost interest in earlier hobbies and other fun because of gaming?"),T("Kya rishton ya logon se dikkat hone par bhi aap zyada gaming karte rehte hain?","Do you keep playing a lot even though it causes problems with other people?"),T("Kya aap ghar waalon ya doosron se apni gaming ka sahi samay chhupate ya jhooth bolte hain?","Have you hidden or lied about how much you play to family or others?"),T("Kya aap buri bhavnaon (dar, udaasi, tanav) se bachne ke liye gaming karte hain?","Do you play to escape or relieve bad feelings such as fear, sadness or stress?"),T("Kya gaming ki wajah se aapne kisi rishte, naukri, ya padhai ka mauka khoya ya khatre me daala?","Have you jeopardised or lost a relationship, job or study opportunity because of gaming?")],calc:function(Z){var $=0,z=0,B=0,D;for(D=0;D<9;D++){var N=Z[D];N!==void 0&&($+=N+1,N==4&&z++,N>=3&&B++)}var G=z>=5,E=G?[9,45,"At or above cut-off",j,2]:B>=3?[9,45,"Some gaming concerns",x,1]:[9,45,"Below cut-off",e,0];return{s:$,b:E,lines:[["Cut-off: 9 me se 5 ya zyada sawalon par 'Bahut aksar' chunne par gaming disorder ke lakshan maane jaate hain. Aapke "+z+" sawal 'Bahut aksar' the. Kul score "+$+" (9 se 45).","Cut-off: choosing 'Very often' on 5 or more of the 9 items suggests gaming disorder. You chose 'Very often' on "+z+". Total score "+$+" (9 to 45)."]],adv:G?["Gaming aapki zindagi par asar daal rahi lagti hai. Ye diagnosis nahi hai. Psychiatrist ya psychologist se milein. Roz ka gaming samay tay karein, raat ko phone door rakhein, aur kisi bharose ke insaan ko bataein. Teen ho to maata-pita ke saath baat karein. Tele-MANAS 14416.","Gaming seems to be affecting your life. This is not a diagnosis. See a psychiatrist or psychologist. Set a daily gaming limit, keep the phone away at night, and tell someone you trust. If you are a teen, talk with your parents. Tele-MANAS 14416."]:B>=3?["Kuch sawalon par 'Aksar' ya 'Bahut aksar' aaya. Gaming ka samay likhkar dekhein aur neend, padhai aur dosti ko pehle rakhein.","You said Often or Very often on several items. Track your gaming time and keep sleep, study and friends first."]:["Cut-off se neeche hai. Gaming abhi dikkat nahi lag rahi.","Below the cut-off. Gaming does not look like a problem right now."]}}});function ta(Z,$,z,B,D,N,G,E){MC.reg({id:Z,name:[$,$],sub:z,max:D.length,opts:a,intro:B,items:D,calc:function(l){var A=0,O;for(O=0;O<D.length;O++)A+=l[O]||0;var _=A>=N;return{s:A,b:_?[0,D.length,"Several points apply",j,2]:A>0?[0,D.length,"Few points apply",b,1]:[0,D.length,"No points apply",e,0],lines:[g],adv:_?E:G}}})}ta("ied","Anger outbursts (explosive anger)",["Achanak bahut tez gusse ke daure, 8 sawal","Sudden, intense anger outbursts, 8 questions"],["Pichhle 12 mahine ke baare me jawab dein. Sharab, nashe ya kisi sharirik bimari ke asar ke bina hue gusse ke baare me sochein.","Answer about the past 12 months. Think about anger that happened without the effect of alcohol, drugs or a physical illness."],[["Kya aap hafte me kam se kam 2 baar, 3 mahine ya zyada, chillate, gaali dete ya dhamki dete hain?","Do you shout, swear or threaten at least twice a week for 3 months or more?"],["Pichhle 1 saal me kya aapne 3 ya zyada baar gusse me cheezein todi ya kisi ko chot pahunchayi?","In the past year, have you damaged things or hurt someone in anger 3 or more times?"],["Kya gussa chhoti si baat par bahut zyada aata hai?","Is your anger far bigger than the small thing that set it off?"],["Kya gussa achanak aata hai, bina pehle se soche?","Does the anger come suddenly, without planning?"],["Kya gusse se pehle tension badhti hai aur baad me raahat milti hai?","Does tension build before the anger and relief follow it?"],["Kya baad me aapko pachtawa, sharm ya afsos hota hai?","Do you feel regret, shame or remorse afterwards?"],["Kya gusse ki wajah se rishton, kaam, padhai ya kanoon me dikkat aayi hai?","Has your anger caused trouble in relationships, work, study or with the law?"],["Kya ye daure sirf sharab ya nashe ke asar me nahi, balki hosh me bhi hote hain?","Do these outbursts happen even when you are sober, not only under alcohol or drugs?"]],5,["Abhi gusse ke daure kam dikhte hain. Gussa aaye to 10 tak ginein, jagah badal lein aur dheere saans lein.","Outbursts look limited for now. When anger rises, count to 10, change place and breathe slowly."],["Kaafi baatein lagu hui. Ye diagnosis nahi hai. Psychiatrist ya clinical psychologist se milein; anger management, CBT aur zaroorat par dawai madad karti hain. Sharab ya nasha ho to pehle use kam karein. Kisi ko chot pahunchane ka darr ho to abhi Tele-MANAS 14416 ya 112 par baat karein.","Many points apply. This is not a diagnosis. See a psychiatrist or clinical psychologist; anger management, CBT and sometimes medicine help. If alcohol or drugs are involved, address that first. If you fear you may hurt someone, call Tele-MANAS 14416 or 112 right now."]),ta("klepto","Kleptomania (urge to steal)",["Churane ki rok na paane wali ichha, 8 sawal","An urge to steal that is hard to resist, 8 questions"],["Pichhle kuch mahine ke baare me jawab dein. Ye sirf unke liye hai jo bina zaroorat ya bina paise ki kami ke churate hain. Ye bahut sensitive vishay hai; aapke jawab yahin rehte hain.","Answer about the past few months. This is only for stealing that is not for need or lack of money. It is a sensitive topic; your answers stay here."],[["Kya aapko aisi cheezein churane ki tez ichha baar-baar hoti hai jise rokna mushkil ho?","Do you have repeated, strong urges to steal that are hard to resist?"],["Kya aap aisi cheezein churate hain jinki aapko zaroorat nahi, ya jo aap kharid sakte the?","Do you steal things you do not need, or could have afforded?"],["Kya churane se pehle tension ya bechaini badhti hai?","Does tension or restlessness build before stealing?"],["Kya churate waqt ya baad me khushi, raahat ya tension ka kam hona mehsoos hota hai?","Do you feel pleasure, relief or less tension while or after stealing?"],["Kya churane ke baad aapko sharm, guilt ya pakde jaane ka darr hota hai?","Do you feel shame, guilt or fear of being caught afterwards?"],["Kya aap gusse, badle ya kisi ajeeb vishwas ya awaaz ke kaaran nahi, bas ichha ki wajah se churate hain?","Do you steal not out of anger, revenge, or a delusion or voice, but because of the urge itself?"],["Kya pakde jaane ya nuksan ke baad bhi aap ye rok nahi paaye?","Have you been unable to stop even after being caught or facing consequences?"],["Kya isse rishton, kaam ya kanoon me dikkat aayi hai?","Has this caused trouble in relationships, work or with the law?"]],5,["Abhi churane ki lat ke lakshan kam dikhte hain. Agar ichha badhe to kisi bharose ke insaan ya counsellor se baat karein.","Signs of a stealing compulsion look limited. If the urge grows, talk to someone you trust or a counsellor."],["Kaafi baatein lagu hui. Ye diagnosis nahi hai aur isme sharm ki zaroorat nahi: ye ek ilaaj yogya impulse-control ki dikkat ho sakti hai. Psychiatrist ya psychologist se milein; therapy (CBT) aur dawai madad karti hain. Agar kanooni dikkat ho to vakeel se bhi salah lein.","Many points apply. This is not a diagnosis, and there is nothing to be ashamed of: it can be a treatable impulse-control problem. See a psychiatrist or psychologist; therapy (CBT) and medicine help. If there are legal issues, also seek a lawyer's advice."]);var P=["self","18+ saal","Ages 18+","Aap khud apne baare me","You, about yourself"];["audit","taps","dast","cudit","assist","ftnd","pgsi","ied","klepto"].forEach(function(Z){MC.who[Z]=P}),MC.who.igds=["self","13+ saal","Ages 13+","Teen ya adult khud","Teen or adult, self"],MC.icd.audit=["Alcohol use disorders","6C40","F10"],MC.icd.taps=["Substance use (screen)","6C4","F10-F19"],MC.icd.dast=["Drug use disorders","6C4","F11-F19"],MC.icd.cudit=["Cannabis use disorders","6C41","F12"],MC.icd.assist=["Substance use disorders","6C4","F10-F19"],MC.icd.ftnd=["Nicotine dependence","6C4A","F17"],MC.icd.pgsi=["Gambling disorder","6C50","F63.0"],MC.icd.igds=["Gaming disorder","6C51","F63.8"],MC.icd.ied=["Intermittent explosive disorder","6C73","F63.8"],MC.icd.klepto=["Kleptomania","6C71","F63.2"];var U=["audit","taps","dast","cudit","assist","ftnd","pgsi","igds","ied","klepto"];U.forEach(function(Z){MC.names[Z]=MC.tests[Z].name[1]}),MC.tabs.a.push({t:["Sharab","Alcohol"],ids:["audit"]},{t:["Nasha aur dawai ka galat istemal","Drugs and medicine misuse"],ids:["taps","dast","cudit","assist"]},{t:["Tobacco","Tobacco"],ids:["ftnd"]},{t:["Jua aur gaming ki lat","Gambling and gaming"],ids:["pgsi","igds"]},{t:["Gussa aur impulse control","Anger and impulse control"],ids:["ied","klepto"]});var ra={},q=[];["a","c"].forEach(function(Z){MC.tabs[Z].forEach(function($){var z=$.ids.filter(function(B){return ra[B]||!MC.tests[B]?!1:(ra[B]=1,!0)});z.length&&q.push({t:$.t,ids:z})})}),MC.groups=q})()}catch(a){setTimeout(function(){throw a})}